using UnityEngine;using UnityEditor;using System;using System.IO;using System.Linq;
public class DungeonTorchAudit : MonoBehaviour {
 Light[] torches;float[] minimum,maximum;int frames;float start;LightObject[] electric;FuseBox fuse;
 const string Report="Temp/DungeonTorchRuntime.txt";
 public void Begin(){var dungeon=Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Building/J_DungeonRoom.prefab"),new Vector3(10000,0,10000),Quaternion.identity,transform);var room=Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Building/CN_Storage.prefab"),new Vector3(10080,0,10000),Quaternion.identity,transform);torches=dungeon.GetComponentsInChildren<Light>(true);if(torches.Length!=4||dungeon.GetComponentsInChildren<LightSwitchInteractable>(true).Length!=0||dungeon.GetComponent<Room>().GetLightObjects().Count!=0)throw new Exception("Dungeon electrical isolation failed");electric=room.GetComponentsInChildren<LightObject>(true);foreach(var e in electric)e.ToggleLight(true);fuse=gameObject.AddComponent<FuseBox>();fuse.SetControlledRooms(new[]{dungeon.GetComponent<Room>(),room.GetComponent<Room>()});fuse.ActivateFuseBox(false);foreach(var e in electric)if(e.IsPowered)throw new Exception("Electric fixture stayed powered");foreach(var t in torches)if(!t.enabled||!t.gameObject.activeInHierarchy)throw new Exception("Torch extinguished by fuse");minimum=torches.Select(t=>float.PositiveInfinity).ToArray();maximum=torches.Select(t=>0f).ToArray();start=Time.time;}
 void Update(){if(torches==null)return;for(int i=0;i<torches.Length;i++){var l=torches[i];minimum[i]=Mathf.Min(minimum[i],l.intensity);maximum[i]=Mathf.Max(maximum[i],l.intensity);if(!l.enabled||!l.gameObject.activeInHierarchy||l.intensity<12*.82f-.001f||l.intensity>12*1.18f+.001f){File.WriteAllText(Report,"FAIL: torch disabled or outside flicker bounds");enabled=false;return;}}frames++;if(Time.time-start<3||frames<60)return;for(int i=0;i<torches.Length;i++)if(maximum[i]-minimum[i]<.05f){File.WriteAllText(Report,"FAIL: static torch "+i);enabled=false;return;}fuse.ActivateFuseBox(true);if(electric.Any(e=>!e.IsPowered))throw new Exception("Electric power restoration failed");foreach(var l in torches){var flicker=l.GetComponent<TorchLightFlicker>();flicker.enabled=false;if(Mathf.Abs(l.intensity-12)>.001f)throw new Exception("Flicker baseline restore failed");flicker.enabled=true;}File.WriteAllText(Report,"PASS: "+frames+" advancing frames over "+(Time.time-start).ToString("F2")+"s; 4 independently animated torches survived fuse off/on; "+electric.Length+" electrical fixtures lost/regained power; disabling flicker restores base intensity.\n"+string.Join("\n",minimum.Select((v,i)=>"Torch "+i+": "+v.ToString("F3")+" to "+maximum[i].ToString("F3"))));Destroy(gameObject);}
}
if(!Application.isPlaying)throw new Exception("Requires Play Mode");var go=new GameObject("Dungeon torch verification");go.AddComponent<DungeonTorchAudit>().Begin();return "Started real-frame torch and fuse regression check";
